import{_ as s,o as a,c as i,a0 as r}from"./chunks/framework.1R7PBCUH.js";const u=JSON.parse('{"title":"Exercises 4","description":"","frontmatter":{},"headers":[],"relativePath":"exercises/exercises4.md","filePath":"exercises/exercises4.md"}'),o={name:"exercises/exercises4.md"};function t(n,e,l,p,d,m){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="exercises-4" tabindex="-1">Exercises 4 <a class="header-anchor" href="#exercises-4" aria-label="Permalink to &quot;Exercises 4&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>These exercises are still in draft. The text isn&#39;t polished yet and new exercises may be added in the future.</p></div><p>Some of these exercises require a user account named <strong>bob</strong>. Create this account now:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bob</span></span></code></pre></div><p>When you&#39;re done with the exercises, remove the account with the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> userdel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bob</span></span></code></pre></div><h2 id="exercise-4-1" tabindex="-1">Exercise 4.1 <a class="header-anchor" href="#exercise-4-1" aria-label="Permalink to &quot;Exercise 4.1&quot;">​</a></h2><p>Convert the following symbolic permissions to octal notation:</p><ul><li><code>rwxr-xr-x</code></li><li><code>rw-------</code></li><li><code>r--r--r--</code></li><li><code>rwxrwx---</code></li></ul><details><summary>Solution</summary><pre>755
600
444
770
</pre></details><p>Convert the following octal permissions to symbolic notation:</p><ul><li><code>644</code></li><li><code>700</code></li><li><code>754</code></li><li><code>640</code></li></ul><details><summary>Solution</summary><pre>rw-r--r--
rwx------
rwxr-xr--
rw-r-----
</pre></details><h2 id="exercise-4-2" tabindex="-1">Exercise 4.2 <a class="header-anchor" href="#exercise-4-2" aria-label="Permalink to &quot;Exercise 4.2&quot;">​</a></h2><p>Set the umask to <code>002</code>.</p><details><summary>Solution</summary><pre>umask 002
</pre></details><p>Create a file named <strong>permissions.txt</strong> in your home directory.</p><details><summary>Solution</summary><pre>cd
touch permissions.txt
</pre></details><p>What permissions do you expect this file to have?</p><details><summary>Answer</summary><pre>rw-rw-r--
</pre></details><p>Verify this by viewing the permissions of this file.</p><details><summary>Solution</summary><pre>ls -l permissions.txt
</pre></details><p>Perform the following changes on <strong>permissions.txt</strong> and verify the result after each change.</p><p>Use octal notation to remove all permissions from the group and others.</p><details><summary>Expected result</summary><pre>rw-------
</pre></details><details><summary>Solution</summary><pre>chmod 600 permissions.txt 
</pre></details><p>Use symbolic notation to add read permission for the group.</p><details><summary>Expected result</summary><pre>rw-r-----
</pre></details><details><summary>Solution</summary><pre>chmod g+r permissions.txt
</pre></details><p>Use octal notation to give all categories the permissions <code>r--</code>.</p><details><summary>Expected result</summary><pre>r--r--r--
</pre></details><details><summary>Solution</summary><pre>chmod 444 permissions.txt
</pre></details><p>Use symbolic notation to add write permission for the owner and remove read permission for others in a single command.</p><details><summary>Expected result</summary><pre>rw-r-----
</pre></details><details><summary>Solution</summary><pre>chmod u+w,o-r permissions.txt
</pre></details><p>Finally, remove the file <strong>permissions.txt</strong>.</p><details><summary>Solution</summary><pre>rm permissions.txt
</pre></details><h2 id="exercise-4-3" tabindex="-1">Exercise 4.3 <a class="header-anchor" href="#exercise-4-3" aria-label="Permalink to &quot;Exercise 4.3&quot;">​</a></h2><p>Give Bob a temporary password and configure his account so that he has to change his password when he first signs in.</p><details><summary>Solution</summary><pre>sudo passwd bob
sudo passwd --expire bob
</pre></details><p>Sign in as Bob and set a password.</p><details><summary>Solution</summary><pre>su bob
</pre></details><p>Return to your own account.</p><details><summary>Solution</summary><pre>exit
</pre></details><h2 id="exercise-4-4" tabindex="-1">Exercise 4.4 <a class="header-anchor" href="#exercise-4-4" aria-label="Permalink to &quot;Exercise 4.4&quot;">​</a></h2><p>Copy the file <strong>lab-materials.zip</strong> from your <strong>Downloads</strong> directory into Bob&#39;s home directory.</p><details><summary>Solution</summary><pre>sudo cp ~/Downloads/lab-materials.zip /home/bob
</pre></details><p>Transfer ownership of this file to Bob&#39;s user account and primary group.</p><details><summary>Solution</summary><pre>sudo chown bob:bob /home/bob/lab-materials.zip
</pre></details><p>Can you combine the previous two steps in a single command? Explain your answer.</p><details><summary>Answer</summary><p>No. To perform this copy, you need access to your own home directory (to read the original file) as well as Bob&#39;s (to write the copy). Only root can do this.</p><p>You can try to use <code>sudo -u bob</code> here but it won&#39;t work because Bob cannot access your <strong>Downloads</strong> directory.</p></details><h2 id="exercise-4-5" tabindex="-1">Exercise 4.5 <a class="header-anchor" href="#exercise-4-5" aria-label="Permalink to &quot;Exercise 4.5&quot;">​</a></h2><p>Create an environment value named <code>MY_NAME</code> that holds your username.</p><details><summary>Solution</summary><pre>export MY_NAME=$USER
</pre></details><p>Sign in as Bob using a <em>non-login</em> shell.</p><details><summary>Solution</summary><pre>su bob
</pre></details><p>Print the value of <code>MY_NAME</code>.</p><details><summary>Solution</summary><pre>echo $MY_NAME
</pre></details><p>Return to your own account.</p><details><summary>Solution</summary><pre>exit
</pre></details><p>Sign in as Bob using a <em>login</em> shell.</p><details><summary>Solution</summary><pre>su - bob
</pre></details><p>Print the variable again. How would you explain what you see?</p><details><summary>Answer</summary><p>A non-login shell inherits the environment of the shell that created it, which is why the <code>MY_NAME</code> variable still exists.</p><p>A login shell starts a fresh environment, so it doesn&#39;t inherit the <code>MY_NAME</code> variable.</p></details><h2 id="exercise-4-6" tabindex="-1">Exercise 4.6 <a class="header-anchor" href="#exercise-4-6" aria-label="Permalink to &quot;Exercise 4.6&quot;">​</a></h2><p>Return to your own account, then lock Bob&#39;s account.</p><details><summary>Solution</summary><pre>sudo passwd -l bob
</pre></details><p>Try to sign in as Bob. What happens, and why do you think this is?</p><details><summary>Answer</summary><p>Even though Bob&#39;s account is locked and he cannot sign in, the shell still prompts you for a password.</p><p>This is a security measure. Announcing that an account is locked would provide important information to an attacker, who can then direct their attention elsewhere. Therefore, the shell always prompts you for a password, even if your account is locked.</p></details><p>Unlock Bob&#39;s account and verify it still works.</p><details><summary>Solution</summary><pre>sudo passwd -u bob
su bob
</pre></details>`,71)])])}const h=s(o,[["render",t]]);export{u as __pageData,h as default};
